    // ------------------------------------------------------------------
    // final assembly
    // ------------------------------------------------------------------

    fn finish(&mut self) -> String {
        let mut s = String::new();
        s.push_str("; generated by wasm2llvm\n");
        s.push_str("target triple = \"x86_64-unknown-linux-gnu\"\n\n");
        for c in &self.consts {
            s.push_str(c);
            s.push('\n');
        }
        s.push('\n');
        for g in &self.globals {
