    fn gen_memory_fill(&mut self) -> Result<(), String> {
        let n = self.pop();
        let val = self.pop();
        let dst = self.pop();
        let sz = self.tmp();
        self.emit(format!("  {} = load i64, ptr @mem.size, align 8", sz));
