        if (len == 0) continue;
        char *save = NULL;
        char *cmd = strtok_r(line, " ", &save);
        if (!cmd) continue;
        if (!strcmp(cmd, "quit")) break;
        if (!strcmp(cmd, "ping")) { printf("ok\n"); continue; }
        if (!strcmp(cmd, "load")) {
            char *id = strtok_r(NULL, " ", &save);
            char *path = strtok_r(NULL, " ", &save);
            if (!id || !path) { printf("error bad args\n"); continue; }
            Mod *m = getmod(id);
            if (!m) { printf("error bad id\n"); continue; }
            m->handle = dlopen(path, RTLD_NOW | RTLD_LOCAL);
            if (!m->handle) { printf("error %s\n", dlerror()); continue; }
            m->init = (void (*)(void))sym(m, "w2l_init");
            if (!m->init) { printf("error no w2l_init\n"); continue; }
            m->used = 1;
            out_reset();
            printf("ok\n");
            continue;
        }
        Mod *m = NULL;
        {
            char *id = NULL;
            /* peek id token without consuming for commands that need it */
            id = strtok_r(NULL, " ", &save);
            (void)id;
            m = NULL;
        }
