        /* The id was consumed above; redo by parsing the original line. */
        char *orig = strdup(line);
        char *save2 = NULL;
        char *c2 = strtok_r(orig, " ", &save2);
        char *id2 = strtok_r(NULL, " ", &save2);
        (void)c2;
        m = getmod(id2 ? id2 : "0");
        if (!strcmp(cmd, "init")) {
            if (!m || !m->used) { printf("error unknown module\n"); continue; }
            trap_code = -1;
            if (setjmp(jb) == 0) { m->init(); printf("ok\n"); }
            else printf("trap %d\n", trap_code);
            out_reset();
        } else if (!strcmp(cmd, "invoke")) {
            char *hexname = strtok_r(NULL, " ", &save2);
            char *nres_s = strtok_r(NULL, " ", &save2);
            if (!m || !m->used || !hexname || !nres_s) { printf("error bad args\n"); continue; }
            int nres = atoi(nres_s);
            static uint8_t args[1 << 16], res[1 << 16];
            memset(args, 0, sizeof args);
            memset(res, 0, sizeof res);
            int nargs = 0;
            char *tok;
            while ((tok = strtok_r(NULL, " ", &save2))) {
                uint8_t buf[16]; size_t bl;
                if (parse_hex(tok, buf, 16, &bl) < 0 || bl != 16) { break; }
                memcpy(SLOT(args, nargs), buf, 16);
                nargs++;
            }
            int trap;
            if (call_export(m, hexname, args, res, &trap) < 0) { printf("error no such export\n"); continue; }
            if (trap >= 0) { printf("trap %d\n", trap); continue; }
            printf("ok");
            for (int i = 0; i < nres; i++) {
                printf(" ");
                print_hex(SLOT(res, i), 16);
            }
            printf("\n");
        } else if (!strcmp(cmd, "global")) {
            char *hexname = strtok_r(NULL, " ", &save2);
            if (!m || !hexname) { printf("error bad args\n"); continue; }
            char symname[512]; namehex(hexname, symname);
            char full[600]; snprintf(full, sizeof full, "w2l_global_%s", symname);
            void (*fn)(uint8_t *) = (void (*)(uint8_t *))sym(m, full);
            if (!fn) { printf("error no such global\n"); continue; }
            uint8_t res[16]; memset(res, 0, 16);
            trap_code = -1;
