F32NAN = "NAN" * 8


def norm(line, results):
    if not line.startswith("ok "):
        return line
    parts = line.split()
    if len(parts) - 1 != len(results):
        return line
    out = ["ok"]
    for r, slotstr in zip(results, parts[1:]):
        if r == "f32" and nan32(int(slotstr[0:8], 16)):
            slotstr = F32NAN
        elif r == "f64" and nan64(int(slotstr[0:16], 16)):
            slotstr = F32NAN
        out.append(slotstr)
    return " ".join(out)


